/* Prototype local. Même disposition T4 P3 R2 ; capture MediaRecorder vraie mais recette uniquement sur appareil simulé. */
(()=>{'use strict';
const $=id=>document.getElementById(id), cfg=JSON.parse($('vv-prise-data').textContent), parts=cfg.parts;
const cam=$('cam'), replay=$('replay'), app=$('app'), body=$('sheetBody');
for(const p of parts){let raw=atob(p.b64),bytes=new Uint8Array(raw.length);for(let j=0;j<raw.length;j++)bytes[j]=raw.charCodeAt(j);p.poster=URL.createObjectURL(new Blob([bytes],{type:'video/mp4'}));delete p.b64;}
let i=0,state='form',stream=null,rec=null,chunks=[],timer=null,raf=0,version=0,didRead=false,blobs={},urls={},fiche=null,busy=false;
const cur=()=>parts[i], p=(k,s)=>$(k).textContent=s;
const fmt=x=>`0:${String(Math.max(0,Math.floor(x))).padStart(2,'0')}`;
function tracksOff(){if(stream){for(const t of stream.getTracks())t.stop();stream=null;}cam.srcObject=null;}
function clear(v){v.pause();v.srcObject=null;v.removeAttribute('src');v.load();v.style.display='none';}
function reset(s){version++;clearTimeout(timer);cancelAnimationFrame(raf);clear(cam);clear(replay);tracksOff();state=s;app.dataset.state=s;app.dataset.prise=cur().id;app.dataset.seance='oui';app.classList.remove('media-error');$('sheet').classList.toggle('hidden',s!=='A');$('scrim').classList.toggle('off',s!=='A');$('rec').classList.toggle('on',s==='B');$('review').classList.toggle('on',s==='C');$('rec').setAttribute('aria-hidden',String(s!=='B'));$('mediaFeedback').hidden=true;didRead=false;}
function list(id,lines,sign){const ul=$(id);ul.replaceChildren(...lines.map(x=>{let li=document.createElement('li'),a=document.createElement('span'),b=document.createElement('span');a.className='mark';a.textContent=sign;b.textContent=x;li.append(a,b);return li;}));}
function hint(){$('scrollHint').hidden=state!=='A'||body.scrollHeight-body.clientHeight<=11||body.scrollTop+body.clientHeight>=body.scrollHeight-13;}
function labels(){let x=cur();p('testID','T4 · PROJECTION');p('sceneCounter',`PRISE ${i+1}/4 · ${x.role}`);[...$('dots').children].forEach((a,j)=>a.classList.toggle('on',j<=i));p('durationLabel',`${x.duree_filmer_s} secondes`);p('sceneTitle',x.titre.toLocaleUpperCase('fr'));p('consigne',x.repere);list('listFilm',x.consignes,'✓');list('listAvoid',[x.a_eviter],'✕');p('caseContext',x.exemple);$('caseContext').hidden=false;p('captureConsent','Avant de filmer quelqu’un, demande son accord.');p('soundText','Le son peut être réécouté mais ne sera pas gardé dans le master muet. Une courte marge technique est enregistrée après le chrono, puis retirée pour respecter la durée choisie.');p('recContext','Filme ta propre offre.');$('recContext').hidden=false;p('reviewContext','Relis ta prise avant de continuer.');$('reviewContext').hidden=false;p('reviewQuestion',x.question);$('voiceZone').hidden=i!==3;p('reviewLabel',`PRISE ${i+1} · ${x.duree_filmer_s} s`);p('reviewOrigin','Ta prise enregistrée');p('next',i===3?'GARDER ET MONTER':'GARDER ET CONTINUER');}
function problem(msg){p('mediaMessage',msg);$('mediaFeedback').hidden=false;$('mediaBack').hidden=false;app.classList.add('media-error');}
function guide(){reset('A');labels();p('cta','FILMER CETTE PRISE');$('cta').disabled=false;cam.muted=true;cam.src=cur().poster;cam.style.display='block';cam.addEventListener('loadedmetadata',()=>{if(state==='A')cam.currentTime=Math.min(1,Math.max(0,cam.duration-.1));},{once:true});cam.load();body.scrollTop=0;requestAnimationFrame(hint);}
function progress(t){let max=cur().duree_filmer_s,j=Math.min(1,t/max);p('chronoVal',fmt(t));$('barFill').style.width=(100*j)+'%';$('bar').classList.toggle('hot',max-t<=2);$('chrono').classList.toggle('hot',max-t<=2);}
async function start(){if(busy||state!=='A')return;busy=true;$('cta').disabled=true;
 try{
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('La caméra nécessite HTTPS ou un atelier local compatible.');
  const mine=version;let s;try{s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:720},height:{ideal:1280}},audio:$('microAudio').checked});}
  catch(err){throw Error('Caméra ou micro indisponible : vérifie les autorisations. Tu peux aussi décocher le micro et réessayer.');}
  if(mine!==version){s.getTracks().forEach(t=>t.stop());return;}
  reset('B');labels();stream=s;cam.style.display='block';cam.muted=true;cam.srcObject=stream;await cam.play();
  const supported=['video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x));if(!supported)throw Error('Ce navigateur ne sait pas enregistrer une vidéo compatible.');
  chunks=[];rec=new MediaRecorder(stream,{mimeType:supported,videoBitsPerSecond:2500000});const currentRec=rec, currentChunks=chunks;currentRec.ondataavailable=e=>{if(e.data?.size)currentChunks.push(e.data);};let cancelled=false;
  currentRec.onstop=()=>{const data=new Blob(currentChunks,{type:currentRec.mimeType});if(rec===currentRec){tracksOff();rec=null;}if(cancelled||state!=='B'||rec!==null)return;if(!data.size){guide();problem('Aucune vidéo enregistrée. Essaie de nouveau.');return;}blobs[cur().id]=data;if(urls[cur().id])URL.revokeObjectURL(urls[cur().id]);urls[cur().id]=URL.createObjectURL(data);review();};
  $('cancelCapture').onclick=()=>{cancelled=true;if(rec?.state==='recording')rec.stop();guide();};
  $('cancelCapture').hidden=false;p('recordLabel','Enregistrement en cours');progress(0);const mark=version;
  currentRec.onstart=()=>{const startTime=performance.now();const tick=()=>{if(mark!==version||state!=='B')return;let t=(performance.now()-startTime)/1000;progress(Math.min(t,cur().duree_filmer_s));if(t>=cur().duree_filmer_s+.40){if(currentRec.state==='recording')currentRec.stop();return;}raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);};currentRec.start(250);
 }catch(e){if(rec?.state==='recording')rec.stop();tracksOff();if(state!=='A')guide();problem(e.message||'Enregistrement impossible. Réessaie.');}finally{busy=false;if(state==='A')$('cta').disabled=false;}
}
function review(){reset('C');labels();p('reviewMode','Lecture de ta prise avec son si le micro était actif');$('redo').disabled=false;$('next').disabled=true;replay.muted=false;replay.controls=true;replay.loop=false;replay.style.display='block';replay.src=urls[cur().id];replay.ontimeupdate=()=>{if(state==='C'&&replay.currentTime>.12){didRead=true;$('next').disabled=false;}};replay.onerror=()=>problem('La prise ne peut pas être relue. Recommence.');replay.load();replay.play().catch(()=>{p('reviewMode','Appuie sur lecture pour revoir ta prise.');});}
function redo(){if(urls[cur().id])URL.revokeObjectURL(urls[cur().id]);delete urls[cur().id];delete blobs[cur().id];guide();}
async function api(path,method='GET',data=null){const headers={'X-T4-Session':cfg.token};if(data&&!(data instanceof Blob)){headers['Content-Type']='application/json';data=JSON.stringify(data);}else if(data)headers['Content-Type']='application/octet-stream';const r=await fetch(path,{method,headers,body:data,cache:'no-store'});let j;try{j=await r.json();}catch{throw Error('Réponse de l’atelier illisible.');}if(!r.ok)throw Error(j.error||'L’atelier a refusé cette action.');return j;}
function readSubtitles(){const s=$('sousTitres').value.trim();if(!s)return [];if(!$('stConfirme').checked)throw Error('Confirme que le texte et les temps ont été vérifiés.');return s.split(/\r?\n/).map(line=>{const a=line.split('|');if(a.length!==3||!/^\s*\d+(?:[.,]\d{1,3})?\s*$/.test(a[0])||!/^\s*\d+(?:[.,]\d{1,3})?\s*$/.test(a[1]))throw Error('Une ligne doit contenir début | fin | texte.');return {debut:Number(a[0].trim().replace(',','.')),fin:Number(a[1].trim().replace(',','.')),texte:a[2].trim()};});}
async function finish(){if(busy||Object.keys(blobs).length!==4)return;busy=true;$('next').disabled=true;
 try{const subtitles=readSubtitles(),voice=$('voiceFile').files[0];if(subtitles.length&&!voice)throw Error('Ajoute d’abord la voix correspondant aux sous-titres.');if(voice&&(!voice.size||voice.size>16*1024*1024))throw Error('Le fichier voix est vide ou dépasse 16 Mio.');p('reviewMode','Envoi local des prises et création du montage…');const j=await api('/api/job','POST',fiche);if(subtitles.length)await api(`/api/job/${j.id}/sous-titres`,'POST',subtitles);for(let n=1;n<=4;n++)await api(`/api/job/${j.id}/S${n}`,'PUT',blobs['S'+n]);if(voice)await api(`/api/job/${j.id}/voix`,'PUT',voice);await api(`/api/job/${j.id}/rendre`,'POST',{});
  for(let n=0;n<600;n++){const q=await api(`/api/job/${j.id}`);p('reviewMode',q.message);if(q.status==='echec')throw Error(q.message);if(q.status==='termine'){tracksOff();const f=await fetch(`/api/job/${j.id}/film`,{headers:{'X-T4-Session':cfg.token},cache:'no-store'});if(!f.ok)throw Error('Téléchargement du montage impossible.');const u=URL.createObjectURL(await f.blob());$('resultFilm').src=u;$('resultDl').href=u;p('resultCredit',q.credit||'Master muet');clear(replay);app.hidden=true;$('result').hidden=false;return;}await new Promise(r=>setTimeout(r,1000));}throw Error('Montage trop long : réessaie dans un nouvel atelier.');
 }catch(e){problem(e.message);$('next').disabled=!didRead;}finally{busy=false;}}
$('cta').onclick=start;$('redo').onclick=redo;$('mediaBack').onclick=()=>{if(state==='C')review();else guide();};$('next').onclick=()=>{if(!didRead||busy)return;if(i<3){i++;guide();}else finish();};
$('scrollHint').onclick=()=>body.scrollBy({top:Math.max(100,body.clientHeight*.8)});body.addEventListener('scroll',hint,{passive:true});window.addEventListener('resize',hint);
$('action').addEventListener('change',()=>{const off=$('action').value==='aucune';$('moyen-zone').hidden=off;$('action-confirm-zone').hidden=off;if(off){$('moyen').value='';$('destination').value='';$('destination_autorisee').checked=false;$('action_confirmee').checked=false;}});
$('fiche-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;let v=Object.fromEntries(new FormData(e.currentTarget));fiche={nom_offre:v.nom_offre,situation_conseillee:v.situation_conseillee,detail_visible:v.detail_visible,accroche:v.accroche,action:v.action,action_confirmee:$('action_confirmee').checked,moyen:v.moyen||'',destination:v.destination||'',destination_autorisee:$('destination_autorisee').checked,nom_affiche:v.nom_affiche||'',lieu_affiche:v.lieu_affiche||'',prix:v.prix||null,devise:v.devise||'',type_prix:v.type_prix||null,prix_confirme:$('prix_confirme').checked};$('fiche-error').hidden=true;
 try{await api('/api/fiche/verifier','POST',fiche);$('fiche-container').hidden=true;app.hidden=false;guide();}catch(err){p('fiche-error',err.message);$('fiche-error').hidden=false;}finally{busy=false;}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='B')$('cancelCapture').click();});
window.addEventListener('pagehide',()=>{if(rec?.state==='recording')rec.stop();tracksOff();Object.values(urls).forEach(URL.revokeObjectURL);});
window.__capture=()=>({state,prise:cur().id,accepted:Object.keys(blobs),videoActive:!!stream,recording:rec?.state==='recording'});document.documentElement.dataset.ready='yes';
})();
